/* === PELCOM COMMON CSS v3 — Jony Ive mode === */
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html,body{overflow-x:hidden}
html{scroll-behavior:smooth;background:var(--black)}

:root{
  --black:#1A1A2E;--dark:#222238;--mid:#2C2C46;
  --blue:#0071e3;--blue-hover:#0077ED;
  --blue-dim:rgba(0,113,227,.06);--white:#fff;
  --cream:#F5F5F7;--cream-2:#E8E8ED;--ink:#1D1D1F;--ink-2:#6E6E73;
  --dim:rgba(255,255,255,.42);--faint:rgba(255,255,255,.04);
  --rule:rgba(255,255,255,.06);--rule-l:rgba(0,0,0,.06);
  --r:28px;--glass:rgba(0,0,0,.82);
}

/* ══ BASE ══ */
body{font-family:'Manrope',system-ui,sans-serif;background:var(--black);color:#f5f5f7;font-size:17px;letter-spacing:-.022em;line-height:1.5;-webkit-font-smoothing:antialiased;overflow-x:hidden}
a{text-decoration:none;color:inherit}
h1,h2,h3,.display,.s-title,.pg-h{font-family:'Unbounded',system-ui,sans-serif;letter-spacing:-.04em}
.num-val,.cert-num,.step-n,.adv-n,.timeline-year{font-family:'Manrope',system-ui,sans-serif}

/* ══ HEADER ══ */
.hd{position:fixed;top:0;left:0;right:0;z-index:300;transition:background .6s;border-bottom:1px solid transparent}
.hd.scrolled{background:var(--glass);backdrop-filter:blur(40px);-webkit-backdrop-filter:blur(40px);border-color:var(--rule)}
.hd-i{max-width:1320px;margin:0 auto;padding:0 56px;height:56px;display:flex;align-items:center;gap:56px}
.logo{display:flex;align-items:center;gap:12px}
.lm{width:28px;height:26px;flex-shrink:0;display:block}
.ln{font-size:18px;font-weight:600;letter-spacing:-.04em}
.hd-nav{display:flex;gap:4px;flex:1}
.hd-nav a{font-size:12px;font-weight:500;letter-spacing:.8px;text-transform:uppercase;color:var(--dim);padding:8px 16px;border-radius:var(--r);transition:color .4s}
.hd-nav a:hover,.hd-nav a.active{color:#fff}
.hd-r{display:flex;align-items:center;gap:28px}
.hd-ph{font-size:12px;font-weight:500;color:var(--dim);transition:color .4s}
.hd-ph:hover{color:#fff}
.hd-btn{font-size:12px;font-weight:500;letter-spacing:-.01em;padding:8px 24px;background:var(--blue)

