and p{font-size:17px;opacity:.85;margin-bottom:36px;color:#fff}
.cta-band .btn-white{background:#fff;color:var(--blue);font-weight:600}
.cta-band .btn-white:hover{background:rgba(255,255,255,.9)}
.cta-actions{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}

